CREATE TABLE IF NOT EXISTS wrld_showcase_profiles(user_id TEXT PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,visible INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS wrld_showcase_votes(voter_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,target_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,stars INTEGER NOT NULL CHECK(stars BETWEEN 1 AND 5),created_at INTEGER NOT NULL,PRIMARY KEY(voter_id,target_id));